pub fn parse<'t, T>(
    input: &'t str,
    file_name: T,
    user_actions: &mut MetaModelicaGrammar<'t>,
) -> Result<ParseTree, ParolError>
where
    T: AsRef<Path>,
{
    use parol_runtime::{
        parser::{parse_tree_type::SynTree, parser_types::SynTreeFlavor},
        syntree::Builder,
    };
    let mut builder = Builder::<SynTree, SynTreeFlavor>::new_with();
    parse_into(input, &mut builder, file_name, user_actions)?;
    Ok(builder.build()?)
}
#[allow(dead_code)]
pub fn parse_into<'t, T: TreeConstruct<'t>>(
    input: &'t str,
    tree_builder: &mut T,
    file_name: impl AsRef<Path>,
    user_actions: &mut MetaModelicaGrammar<'t>,
) -> Result<(), ParolError>
where
    ParolError: From<T::Error>,
{
    use meta_modelica_grammar_scanner::MetaModelicaGrammarScanner;
    let mut lr_parser = LRParser::new(
        238,
        &PARSE_TABLE,
        PRODUCTIONS,
        TERMINAL_NAMES,
        NON_TERMINALS,
    );
    // Initialize wrapper
    let mut user_actions = MetaModelicaGrammarAuto::new(user_actions);
    let scanner = MetaModelicaGrammarScanner::new();
    lr_parser.parse_into(
        tree_builder,
        TokenStream::new(
            input,
            file_name,
            scanner.scanner_impl.clone(),
            &MetaModelicaGrammarScanner::match_function,
            1,
        )
        .unwrap(),
        &mut user_actions,
    )
}
